fn fmat(rows: &[Vec<F>]) -> Matrix {
    let n = rows.len();
    let d = rows.first().map_or(0, |r| r.len());
    Matrix::from_fn(n, d, |i, j| rows[i][j].0)
}

impl Draws {
    fn draws(&self) -> MatheronPathDraws {
        MatheronPathDraws {
            frequencies: fmat(&self.frequencies),
            weights: fmat(&self.weights),
            noise: fmat(&self.noise),
        }
    }
}

