fn fixture_dir() -> PathBuf {
    common::fixture_dir().join("phase8_so_acquisition")
}

fn load() -> Vec<Fixture> {
    let mut out = Vec::new();
    let mut paths: Vec<_> = std::fs::read_dir(fixture_dir())
        .expect("phase-8 fixtures (scripts/generate_fixtures.py --phase 8-so-acquisition)")
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "json"))
        .collect();
    paths.sort();
    for p in paths {
        let text = std::fs::read_to_string(&p).unwrap();
        out.push(serde_json::from_str(&text).unwrap_or_else(|e| panic!("{p:?}: {e}")));
    }
    assert!(!out.is_empty(), "no phase-8 fixtures");
    out
}

// ---------------------------------------------------------------------------
// Builders
// ---------------------------------------------------------------------------

fn build_member(f: &ModelSpec) -> BatchedMultiOutputGP {
    let c = &f.config;
    let x: Vec<Matrix> = f.train_x.iter().map(|b| matrix(b)).collect();
    let y: Vec<Matrix> = f.train_y.iter().map(|b| matrix(b)).collect();
    let mut options = BatchedMultiOutputGPOptions {
        train_yvar: f
            .train_yvar
            .as_ref()
            .map(|v| v.iter().map(|b| matrix(b)).collect()),
        ..Default::default()
    };
    match c.covar.as_str() {
        "rbf" => {}
        "matern" => options.kernel = KernelKind::Matern52,
        other => panic!("unknown covar {other}"),
    }
    options.input_transform = match c.normalize.as_deref() {
        None => None,
        Some("shared") => Some(BatchedInputTransform::Shared(Normalize::new(c.d))),
        Some(other) => panic!("unknown normalize {other}"),
    };
    if c.outcome == "none" {
        options.outcome_transform = OutcomeTransformChoice::None;
    }
    let mut model = BatchedMultiOutputGP::new(x, y, vec![], options).unwrap();
    assert_eq!(model.num_outputs(), c.m);
    model.set_raw_parameters(&f.raw_params).unwrap();
    model
}

fn build_model(f: &Fixture) -> Arc<dyn Model> {
    let members: Vec<BatchedMultiOutputGP> = f.models.iter().map(build_member).collect();
    match f.kind.as_str() {
        "single_task" => Arc::new(members.into_iter().next().unwrap()),
        "model_list" => Arc::new(ModelListGP::new(members).unwrap()),
        other => panic!("unknown kind {other}"),
    }
}

fn sampler(base: &[Vec<f64>]) -> Arc<SobolQMCNormalSampler> {
    let s = SobolQMCNormalSampler::new(base.len(), Some(SEED)).unwrap();
    s.set_base_samples(matrix(base)).unwrap();
    Arc::new(s)
}

fn sampler_dims(draws: &[Vec<Vec<f64>>]) -> Arc<SobolQMCNormalSampler> {
    let s = SobolQMCNormalSampler::new(draws[0].len(), Some(SEED)).unwrap();
    for z in draws {
        s.set_base_samples(matrix(z)).unwrap();
    }
    Arc::new(s)
}

fn transform(w: &Option<Vec<f64>>) -> Option<ScalarizedPosteriorTransform> {
    w.as_ref()
        .map(|w| ScalarizedPosteriorTransform::new(Vector::from_vec(w.clone()), 0.0).unwrap())
}

fn opt_matrix(m: &Option<Vec<Vec<f64>>>) -> Option<Matrix> {
    m.as_ref().map(|m| matrix(m))
}

// ---------------------------------------------------------------------------
// Comparisons
// ---------------------------------------------------------------------------

/// The values and gradients of `acqf` at the candidate sets of `e`.
fn evaluate(acqf: &dyn AcquisitionFunction, e: &Eval) -> (Vec<f64>, Vec<f64>) {
    let mut values = Vec::new();
    let mut grads = Vec::new();
    for x in &e.x {
        let (v, g) = acqf.forward_with_grad(&matrix(x)).unwrap();
        values.push(v);
        grads.extend(matrix_rows(&g));
    }
    (values, grads)
}

fn check_eval(r: &mut Report, fixture: &str, name: &str, acqf: &dyn AcquisitionFunction, e: &Eval) {
    let (values, grads) = evaluate(acqf, e);
    r.check_slices(
        fixture,
        &format!("{name} values"),
        &values,
        &fvec(&e.values),
        VALUE_TOL,
    );
    if let Some(g) = &e.grads {
        let expected: Vec<f64> = g.iter().flatten().flatten().copied().collect();
        r.check_slices_atol(
            fixture,
            &format!("{name} gradients"),
            &grads,
            &expected,
            GRAD_TOL,
            GRAD_ATOL,
        );
    } else {
        check_fd(r, fixture, name, acqf, e);
    }
}

/// The gradients of `acqf` against central differences of its values.
fn check_fd(r: &mut Report, fixture: &str, name: &str, acqf: &dyn AcquisitionFunction, e: &Eval) {
    let h = 1e-6;
    let mut actual = Vec::new();
    let mut expected = Vec::new();
    for x in &e.x {
        let x = matrix(x);
        let (_, g) = acqf.forward_with_grad(&x).unwrap();
        for i in 0..x.nrows() {
            for j in 0..x.ncols() {
                let mut up = x.clone();
                let mut dn = x.clone();
                up[(i, j)] += h;
                dn[(i, j)] -= h;
                let fd = (acqf.forward(&up).unwrap() - acqf.forward(&dn).unwrap()) / (2.0 * h);
                actual.push(g[(i, j)]);
                expected.push(fd);
            }
        }
    }
    r.check_slices(
        fixture,
        &format!("{name} gradients vs finite differences"),
        &actual,
        &expected,
        FD_TOL,
    );
}

