#[test]
fn parity_knowledge_gradient() {
    let mut r = Report::default();
    for f in load() {
        let model = build_model(&f);
        for c in &f.kg {
            let options = QKnowledgeGradientOptions {
                num_fantasies: Some(c.num_fantasies),
                sampler: Some(sampler(&c.base_samples)),
                objective: c.objective.as_ref().map(|w| {
                    Arc::new(LinearMcObjective::new(Vector::from_vec(w.clone())).unwrap())
                        as Arc<dyn botorch_core::acquisition::McObjective>
                }),
                posterior_transform: transform(&c.transform),
                inner_sampler: c.inner_base_samples.as_ref().map(|z| sampler(z)),
                x_pending: opt_matrix(&c.pending),
                current_value: c.current_value,
            };
            let acqf = QKnowledgeGradient::new(Arc::clone(&model), options).unwrap();
            assert_eq!(acqf.get_augmented_q_batch_size(c.q), c.q + c.num_fantasies);
            check_eval(
                &mut r,
                &f.name,
                &format!("qKG {}", c.variant),
                &acqf,
                &c.eval,
            );
        }
        for c in f.mfkg.iter().flatten() {
            let d = model.dim();
            let cost = c.cost.as_ref().map(|c| {
                let cm =
                    AffineFidelityCostModel::new(Some(&c.fidelity_weights), c.fixed_cost).unwrap();
                Arc::new(InverseCostWeightedUtility::new(Arc::new(cm), true, None, false).unwrap())
                    as Arc<dyn botorch_core::acquisition::cost_aware::CostAwareUtility>
            });
            let options = QMultiFidelityKnowledgeGradientOptions {
                kg: QKnowledgeGradientOptions {
                    num_fantasies: Some(c.num_fantasies),
                    sampler: Some(sampler(&c.base_samples)),
                    current_value: c.current_value,
                    ..Default::default()
                },
                cost_aware_utility: cost,
                project: Some(Arc::new(
                    TargetFidelityProjection::new(c.target_fidelities.clone(), d).unwrap(),
                ) as Arc<dyn InputProjection>),
                expand: c.expand.as_ref().map(|e| {
                    Arc::new(TraceObservationExpansion::new(
                        Some(e.fidelity_dims.clone()),
                        e.num_trace_obs,
                    )) as Arc<dyn InputProjection>
                }),
                value_function: None,
            };
            let acqf = QMultiFidelityKnowledgeGradient::new(Arc::clone(&model), options).unwrap();
            check_eval(
                &mut r,
                &f.name,
                &format!("qMFKG {}", c.variant),
                &acqf,
                &c.eval,
            );
        }
    }
    r.finish("qKnowledgeGradient / qMultiFidelityKnowledgeGradient vs BoTorch");
}

#[test]
fn parity_noisy_expected_improvement_and_mc() {
    let mut r = Report::default();
    for f in load() {
        let model = build_model(&f);
        let baseline = matrix(&f.baseline);
        for c in &f.nei {
            assert_eq!(c.draws[0].len(), c.num_samples);
            let options = QNoisyExpectedImprovementOptions {
                sampler: Some(sampler_dims(&c.draws)),
                x_pending: opt_matrix(&c.pending),
                objective: c.objective.as_ref().map(|w| {
                    Arc::new(LinearMcObjective::new(Vector::from_vec(w.clone())).unwrap())
                        as Arc<dyn botorch_core::acquisition::McObjective>
                }),
                prune_baseline: false,
                cache_root: c.cache_root,
                ..Default::default()
            };
            let acqf =
                QNoisyExpectedImprovement::new(Arc::clone(&model), &baseline, options).unwrap();
            let name = format!("qNEI cache_root={}", c.cache_root);
            check_eval(&mut r, &f.name, &name, &acqf, &c.eval);
        }
        for c in &f.mc {
            let m = ScalarizedModel::wrap(Arc::clone(&model), transform(&c.transform)).unwrap();
            let options = McAcquisitionOptions {
                sampler: Some(sampler(&c.base_samples)),
                ..Default::default()
            };
            let acqf: Box<dyn AcquisitionFunction> = match c.name.as_str() {
                "qLowerConfidenceBound" => {
                    Box::new(QLowerConfidenceBound::new(m, c.beta.unwrap(), options).unwrap())
                }
                "qPosteriorStandardDeviation" => {
                    Box::new(QPosteriorStandardDeviation::new(m, options).unwrap())
                }
                other => panic!("unknown {other}"),
            };
            check_eval(&mut r, &f.name, &c.name, acqf.as_ref(), &c.eval);
        }
    }
    r.finish("qNEI / qLCB / qPSTD vs BoTorch");
}

#[test]
fn parity_analytic() {
    let mut r = Report::default();
    for f in load() {
        let model = build_model(&f);
        let baseline = matrix(&f.baseline);
        for c in &f.analytic.nei {
            let s = Some(sampler(&c.base_samples));
            let (acqf, best): (Box<dyn AcquisitionFunction>, Vec<f64>) = if c.log {
                let a = LogNoisyExpectedImprovement::new(
                    Arc::clone(&model),
                    &baseline,
                    c.num_fantasies,
                    c.maximize,
                    s,
                    None,
                )
                .unwrap();
                let b = a.best_f().to_vec();
                (Box::new(a), b)
            } else {
                let a = NoisyExpectedImprovement::new(
                    Arc::clone(&model),
                    &baseline,
                    c.num_fantasies,
                    c.maximize,
                    s,
                )
                .unwrap();
                let b = a.best_f().to_vec();
                (Box::new(a), b)
            };
            let name = if c.log { "LogNEI" } else { "NEI" };
            r.check_slices(
                &f.name,
                &format!("{name} best_f"),
                &best,
                &c.best_f,
                VALUE_TOL,
            );
            check_eval(&mut r, &f.name, name, acqf.as_ref(), &c.eval);
        }
        for c in &f.analytic.logpf {
            let acqf = LogProbabilityOfFeasibility::new(Arc::clone(&model), c.constraints.clone())
                .unwrap();
            check_eval(
                &mut r,
                &f.name,
                "LogProbabilityOfFeasibility",
                &acqf,
                &c.eval,
            );
        }
        for c in &f.analytic.qpi {
            let m = ScalarizedModel::wrap(Arc::clone(&model), transform(&c.transform)).unwrap();
            let acqf = QAnalyticProbabilityOfImprovement::new(m, c.best_f, c.maximize).unwrap();
            check_eval(
                &mut r,
                &f.name,
                "qAnalyticProbabilityOfImprovement",
                &acqf,
                &c.eval,
            );
        }
        if let Some(c) = &f.analytic.spm {
            let acqf = ScalarizedPosteriorMean::new(
                Arc::clone(&model),
                Vector::from_vec(c.weights.clone()),
            )
            .unwrap();
            check_eval(&mut r, &f.name, "ScalarizedPosteriorMean", &acqf, &c.eval);
        }
    }
    r.finish("analytic NEI / LogPF / ScalarizedPosteriorMean vs BoTorch");
}

fn mes_options(c: &Mes) -> MaxValueEntropyOptions {
    MaxValueEntropyOptions {
        num_mv_samples: c.max_values.len(),
        posterior_transform: c.transform.as_ref().map(|(w, o)| {
            ScalarizedPosteriorTransform::new(Vector::from_vec(w.clone()), *o).unwrap()
        }),
        maximize: c.maximize,
        x_pending: opt_matrix(&c.pending),
        num_fantasies: 4,
        num_y_samples: 16,
        sampler: c.y_base_samples.as_ref().map(|z| sampler(z)),
        fantasies_sampler: c.fantasy_base_samples.as_ref().map(|z| sampler(z)),
        seed: Some(SEED),
        ..Default::default()
    }
}

#[test]
fn parity_max_value_entropy() {
    let mut r = Report::default();
    for f in load() {
        let model = build_model(&f);
        let d = model.dim();
        for c in f.mes.iter().flatten() {
            let cs = matrix(&c.candidate_set);
            let o = mes_options(c);
            let mf = |o: MaxValueEntropyOptions| MultiFidelityMaxValueEntropyOptions {
                mes: o,
                cost_aware_utility: None,
                project: c.target_fidelities.as_ref().map(|t| {
                    Arc::new(TargetFidelityProjection::new(t.clone(), d).unwrap())
                        as Arc<dyn InputProjection>
                }),
                expand: c.expand.as_ref().map(|e| {
                    Arc::new(TraceObservationExpansion::new(
                        Some(e.fidelity_dims.clone()),
                        e.num_trace_obs,
                    )) as Arc<dyn InputProjection>
                }),
            };
            let m = Arc::clone(&model);
            let name = format!("{} {}", c.cls, c.variant);
            match c.cls.as_str() {
                "qMaxValueEntropy" => {
                    let a = QMaxValueEntropy::new(m, &cs, o).unwrap();
                    a.set_posterior_max_values(c.max_values.clone()).unwrap();
                    check_eval(&mut r, &f.name, &name, &a, &c.eval);
                }
                "qLowerBoundMaxValueEntropy" => {
                    let a = QLowerBoundMaxValueEntropy::new(m, &cs, o).unwrap();
                    a.set_posterior_max_values(c.max_values.clone()).unwrap();
                    check_eval(&mut r, &f.name, &name, &a, &c.eval);
                }
                "qMultiFidelityMaxValueEntropy" => {
                    let a = QMultiFidelityMaxValueEntropy::new(m, &cs, mf(o)).unwrap();
                    a.as_mes()
                        .set_posterior_max_values(c.max_values.clone())
                        .unwrap();
                    check_eval(&mut r, &f.name, &name, &a, &c.eval);
                }
                "qMultiFidelityLowerBoundMaxValueEntropy" => {
                    let a = QMultiFidelityLowerBoundMaxValueEntropy::new(m, &cs, mf(o)).unwrap();
                    a.as_gibbon()
                        .set_posterior_max_values(c.max_values.clone())
                        .unwrap();
                    check_eval(&mut r, &f.name, &name, &a, &c.eval);
                }
                other => panic!("unknown {other}"),
            }
        }
    }
    r.finish("max-value entropy search vs BoTorch");
}

#[test]
fn parity_optimal_samples_and_entropy_search() {
    let mut r = Report::default();
    for f in load() {
        let model = build_model(&f);
        let o = &f.optimal_samples;
        let options = OptimalSamplesOptions {
            raw_samples: o.raw_samples,
            num_restarts: o.num_restarts,
            transform: match transform(&o.transform) {
                Some(t) => SampleTransform::Scalarize(t),
                None => SampleTransform::Identity,
            },
            num_features: 2 * o.draws[0].frequencies.len(),
            draws: Some(o.draws.iter().map(Draws::draws).collect()),
            candidates: Some(matrix(&o.candidates)),
            ..Default::default()
        };
        let (xo, fo) =
            get_optimal_samples(model.as_ref(), &matrix(&o.bounds), o.num_optima, &options)
                .unwrap();
        r.check_slices(
            &f.name,
            "get_optimal_samples inputs",
            &matrix_rows(&xo),
            &common::flatten(&o.optimal_inputs),
            OPT_TOL,
        );
        r.check_slices(
            &f.name,
            "get_optimal_samples outputs",
            &matrix_rows(&fo),
            &common::flatten(&o.optimal_outputs),
            OPT_TOL,
        );
        let xo = matrix(&o.optimal_inputs);
        let fo = matrix(&o.optimal_outputs);
        for c in &f.jes {
            let options = QJointEntropySearchOptions {
                condition_noise: c.condition_noise.clone(),
                posterior_transform: transform(&c.transform),
                x_pending: opt_matrix(&c.pending),
                estimation_type: JesEstimationType::from_name(&c.estimation_type).unwrap(),
                sampler: c.base_samples.as_ref().map(|z| sampler(z)),
                ..Default::default()
            };
            let acqf = QJointEntropySearch::new(Arc::clone(&model), &xo, &fo, options).unwrap();
            let name = format!("qJES {}", c.estimation_type);
            check_eval(&mut r, &f.name, &name, &acqf, &c.eval);
        }
        for c in f.pes.iter().flatten() {
            let options = QMultiObjectivePredictiveEntropySearchOptions {
                maximize: c.maximize,
                ..Default::default()
            };
            let acqf = QPredictiveEntropySearch::new(
                Arc::clone(&model),
                &matrix(&c.optimal_inputs),
                options,
            )
            .unwrap();
            check_eval(&mut r, &f.name, "qPES", &acqf, &c.eval);
        }
        for c in &f.ts {
            let options = PathwiseThompsonSamplingOptions {
                posterior_transform: transform(&c.transform),
                num_features: 2 * c.draws[0].frequencies.len(),
                ..Default::default()
            };
            let acqf = PathwiseThompsonSampling::new(Arc::clone(&model), options).unwrap();
            acqf.redraw(c.q, Some(c.draws.iter().map(Draws::draws).collect()))
                .unwrap();
            check_eval(&mut r, &f.name, "PathwiseThompsonSampling", &acqf, &c.eval);
        }
        for c in &f.nipv {
            let acqf = QNegIntegratedPosteriorVariance::new(
                Arc::clone(&model),
                &matrix(&c.mc_points),
                transform(&c.transform),
                opt_matrix(&c.pending),
            )
            .unwrap();
            check_eval(&mut r, &f.name, "qNIPV", &acqf, &c.eval);
        }
    }
    r.finish("optimal samples / qJES / qPES / Thompson sampling / qNIPV vs BoTorch");
}

/// The prior `exp(-0.5 ||(x - 0.5) / 0.3||²)` of every point (its log with
/// `log`).
fn prior(log: bool) -> PriorModule {
    PriorModule::new(move |x: &Matrix, with_grad: bool| {
        let (n, d) = x.shape();
        let lp = Vector::from_fn(n, |i, _| {
            -0.5 * (0..d)
                .map(|k| ((x[(i, k)] - 0.5) / 0.3).powi(2))
                .sum::<f64>()
        });
        let v = if log { lp.clone() } else { lp.map(f64::exp) };
        let pullback = with_grad.then(|| {
            let x = x.clone();
            let v = v.clone();
            Box::new(move |bar: &Vector| {
                Ok(Matrix::from_fn(n, d, |i, k| {
                    let dlp = -(x[(i, k)] - 0.5) / 0.09;
                    bar[i] * if log { dlp } else { v[i] * dlp }
                }))
            }) as PointPullback
        });
        Ok((v, pullback))
    })
}

#[test]
fn parity_wrappers() {
    let mut r = Report::default();
    for f in load() {
        let Some(w) = &f.wrappers else { continue };
        let model = build_model(&f);
        let d = model.dim();
        let init = Vector::from_vec(w.init_point.clone());
        let ei: Arc<dyn AcquisitionFunction> =
            Arc::new(ExpectedImprovement::new(Arc::clone(&model), w.best_f, true).unwrap());
        for c in &w.penalized {
            let penalty: Arc<dyn Penalty> = match c.penalty.as_str() {
                "L2" => Arc::new(L2Penalty::new(init.clone())),
                "L1" => Arc::new(L1Penalty::new(init.clone())),
                "Gaussian" => Arc::new(GaussianPenalty::new(init.clone(), 0.5)),
                "GroupLasso" => Arc::new(GroupLassoPenalty::new(
                    init.clone(),
                    vec![vec![0, 2], vec![1]],
                )),
                "L0" => Arc::new(L0PenaltyApprox::new(init.clone(), 0.25)),
                other => panic!("unknown {other}"),
            };
            let acqf = PenalizedAcquisitionFunction::new(Arc::clone(&ei), penalty, 0.3);
            check_eval(
                &mut r,
                &f.name,
                &format!("Penalized {}", c.penalty),
                &acqf,
                &c.eval,
            );
        }
        let objective = Arc::new(PenalizedMcObjective::new(
            Arc::new(IdentityMcObjective),
            Arc::new(L1PenaltyObjective::new(init.clone())),
            0.2,
        ));
        let acqf = QExpectedImprovement::new(
            Arc::clone(&model),
            w.best_f,
            McAcquisitionOptions {
                sampler: Some(sampler(&w.penalized_objective.base_samples)),
                objective: Some(objective),
                ..Default::default()
            },
        )
        .unwrap();
        check_eval(
            &mut r,
            &f.name,
            "qEI PenalizedMCObjective",
            &acqf,
            &w.penalized_objective.eval,
        );
        for c in &w.proximal {
            let gp = model.output_gps().unwrap()[0];
            let x = gp.train_inputs();
            let last = Vector::from_fn(d, |k, _| x[(x.nrows() - 1, k)]);
            let acqf = ProximalAcquisitionFunction::new(
                Arc::clone(&ei),
                Vector::from_vec(c.weights.clone()),
                last,
                gp.input_transform().cloned(),
                c.transformed_weighting,
                c.beta,
            )
            .unwrap();
            check_eval(&mut r, &f.name, "Proximal", &acqf, &c.eval);
        }
        let ff = &w.fixed_feature;
        let qei: Arc<dyn AcquisitionFunction> = Arc::new(
            QExpectedImprovement::new(
                Arc::clone(&model),
                w.best_f,
                McAcquisitionOptions {
                    sampler: Some(sampler(&ff.base_samples)),
                    ..Default::default()
                },
            )
            .unwrap(),
        );
        let acqf =
            FixedFeatureAcquisitionFunction::new(qei, d, ff.columns.clone(), matrix(&ff.values))
                .unwrap();
        check_eval(&mut r, &f.name, "FixedFeature", &acqf, &ff.eval);
        for c in &w.prior_guided {
            let base: Arc<dyn AcquisitionFunction> = match c.base.as_str() {
                "qExpectedImprovement" => Arc::new(
                    QExpectedImprovement::new(
                        Arc::clone(&model),
                        w.best_f,
                        McAcquisitionOptions {
                            sampler: c.base_samples.as_ref().map(|z| sampler(z)),
                            ..Default::default()
                        },
                    )
                    .unwrap(),
                ),
                "qLogExpectedImprovement" => Arc::new(
                    QLogExpectedImprovement::new(
                        Arc::clone(&model),
                        w.best_f,
                        QLogExpectedImprovementOptions {
                            sampler: c.base_samples.as_ref().map(|z| sampler(z)),
                            ..Default::default()
                        },
                    )
                    .unwrap(),
                ),
                "ExpectedImprovement" => Arc::clone(&ei),
                "LogExpectedImprovement" => Arc::new(
                    LogExpectedImprovement::new(Arc::clone(&model), w.best_f, true).unwrap(),
                ),
                other => panic!("unknown {other}"),
            };
            let acqf = PriorGuidedAcquisitionFunction::new(
                base,
                prior(c.log),
                c.log,
                0.75,
                opt_matrix(&c.pending),
            )
            .unwrap();
            let name = format!("PriorGuided {} pending={}", c.base, c.pending.is_some());
            check_eval(&mut r, &f.name, &name, &acqf, &c.eval);
        }
    }
    r.finish("penalties and wrappers vs BoTorch");
}

#[test]
fn parity_optimize_acqf_from_identical_initial_conditions() {
    let mut r = Report::default();
    for f in load() {
        let model = build_model(&f);
        for c in f.optimize.iter().flatten() {
            let acqf: Box<dyn AcquisitionFunction> = match c.acqf.as_str() {
                "qKnowledgeGradient" => Box::new(
                    QKnowledgeGradient::new(
                        Arc::clone(&model),
                        QKnowledgeGradientOptions {
                            num_fantasies: c.num_fantasies,
                            sampler: c.base_samples.as_ref().map(|z| sampler(z)),
                            ..Default::default()
                        },
                    )
                    .unwrap(),
                ),
                "qLowerBoundMaxValueEntropy" => {
                    let mv = c.max_values.clone().unwrap();
                    let a = QLowerBoundMaxValueEntropy::new(
                        Arc::clone(&model),
                        &matrix(c.candidate_set.as_ref().unwrap()),
                        MaxValueEntropyOptions {
                            num_mv_samples: mv.len(),
                            seed: Some(SEED),
                            ..Default::default()
                        },
                    )
                    .unwrap();
                    a.set_posterior_max_values(mv).unwrap();
                    Box::new(a)
                }
                other => panic!("unknown {other}"),
            };
            let options = OptimizeAcqfOptions {
                batch_initial_conditions: Some(c.ics.iter().map(|b| matrix(b)).collect()),
                ..Default::default()
            };
            let k = c.values.len();
            let res = optimize_acqf_detailed(acqf.as_ref(), &matrix(&c.bounds), 1, k, 0, &options)
                .unwrap();
            let mut agree = 0;
            let mut worst_x: f64 = 0.0;
            for (i, restart) in res.restarts.iter().enumerate() {
                let e = c.values[i];
                if (restart.acq_value - e).abs() <= OPT_TOL * e.abs().max(1.0) {
                    agree += 1;
                    // The candidates (without the fantasy points of qKG).
                    let ex: Vec<f64> = c.candidates[i].iter().flatten().copied().collect();
                    let x = matrix_rows(&restart.candidates);
                    worst_x = worst_x.max(common::rel_err(&x[..ex.len()], &ex));
                }
            }
            let name = format!("optimize_acqf {}", c.acqf);
            r.check(
                &f.name,
                &format!("{name}: restarts below BoTorch's value"),
                (k - agree) as f64,
                1.0,
            );
            r.check(
                &f.name,
                &format!("{name}: candidates (agreeing restarts)"),
                worst_x,
                1e-3,
            );
        }
    }
    r.finish("optimize_acqf from BoTorch's initial conditions");
}
